'use strict';
const $=q=>document.querySelector(q);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const fmtShort=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});
let csrfToken=null;
let account=null;
const api=async(url,body)=>{
  const opts={credentials:'same-origin'};
  if(body!==undefined){opts.method='POST';opts.headers={'Content-Type':'application/json'};if(csrfToken&&!['/api/login','/api/register'].includes(url))opts.headers['X-CSRF-Token']=csrfToken;opts.body=JSON.stringify(body);}
  const r=await fetch(url,opts);
  const data=await r.json();
  if(!r.ok){if(r.status===401&&url!='/api/login'&&url!='/api/register'){csrfToken=null;account=null;showAuth();}throw Error(data.error||'The server returned an error');}
  return data;
};
const state={content:null,progress:null,view:'today',selectedDay:1,subject:'PS',lesson:null,search:'',month:'all',lab:'bayes',labParams:{prev:5,sens:90,fpr:10,a:1,b:0.5,c:0,d:1,x:3,lr:0.24,steps:6,alg:'BFS',step:0},quiz:null,result:null,practiceSub:'ALL',practiceCount:15,practiceDifficulty:'all',focus:false,flashMode:'due',flashSub:'ALL',flashIndex:0,flashRevealed:false,diceSum:7,pyA:-7,pyB:3};
const lessons=()=>state.content.lessons;
const days=()=>state.content.days;
const qs=()=>state.content.questions;
const lessonById=id=>lessons().find(x=>x.id===id);
const dayByNumber=n=>days()[n-1];
const dayByDate=d=>days().find(x=>x.date===d);
const subjectById=id=>state.content.subjects.find(x=>x.id===id);
const qById=id=>qs().find(x=>x.id===id);
const dayDone=d=>['read','practice','recall'].every(t=>state.progress.day_tasks[d]?.[t]);
const completedTopics=()=>lessons().filter(l=>state.progress.topics[l.id]).length;
const percent=(a,b)=>b?Math.round(100*a/b):0;
const subjectPercent=s=>percent(lessons().filter(l=>l.subject===s&&state.progress.topics[l.id]).length,lessons().filter(l=>l.subject===s).length);
const activeDay=()=>dayByNumber(state.selectedDay);
let timerInterval=null;
let toastTimer;
const badge=s=>`<span class="pill subject-pill" style="background:${subjectById(s)?.color||'#777'}19;color:${subjectById(s)?.color||'#555'}">${esc(s)}</span>`;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function updateSide(){let done=completedTopics(),count=lessons().length;$('#side-percent').textContent=`${percent(done,count)}%`;$('#side-done').textContent=done;$('#side-total').textContent=count;$('#side-bar').style.width=`${percent(done,count)}%`;
 document.querySelectorAll('#nav .nav-button, .settings-button').forEach(el=>el.classList.toggle('active',el.dataset.view===({'day':'roadmap','lesson':'syllabus','syllabus-detail':'syllabus','quiz':'practice','result':'practice'}[state.view]||state.view)));
 const labels={today:'Today',roadmap:'89-day roadmap',day:`Day ${state.selectedDay}`,syllabus:'Syllabus', 'syllabus-detail':subjectById(state.subject)?.name,lesson:'Concept lesson',flashcards:'Active recall',practice:'Practice',quiz:'Quiz session',result:'Answer review',labs:'Concept labs',insights:'Performance',settings:'Settings'};
 $('#breadcrumbs').textContent='Preparation / '+(labels[state.view]||'StudyOS');
}
function render(scroll=true){if(!state.content)return;updateSide();const view={today:renderToday,roadmap:renderRoadmap,day:renderDay,syllabus:renderSyllabus,'syllabus-detail':renderSubject,lesson:renderLesson,flashcards:renderFlashcards,practice:renderPractice,quiz:renderQuiz,result:renderResult,labs:renderLabs,insights:renderInsights,settings:renderSettings}[state.view];$('#main').innerHTML=view?view():renderToday();if(scroll)window.scrollTo({top:0,behavior:'instant'});if(state.view==='labs')refreshLab();if(state.view==='quiz')startTimer();}
function goto(view,options={}){clearInterval(timerInterval);if(view==='day'&&options.number)state.selectedDay=Number(options.number);if(view==='lesson'&&options.id)state.lesson=options.id;if(view==='syllabus-detail'&&options.subject)state.subject=options.subject;if(view==='labs'&&options.lab)state.lab=options.lab;state.view=view;$('#sidebar').classList.remove('open');render();}
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${action}</div>`;}
function stat(label,value,foot){return `<div class="stat"><div class="stat-label">${esc(label)}</div><div class="stat-value">${esc(value)}</div><div class="stat-foot">${esc(foot)}</div></div>`;}
function progressBar(v){return `<div class="progress-track"><div class="progress-fill" style="width:${v}%"></div></div>`;}
function checklistTask(day,task,label,hint){const done=!!state.progress.day_tasks[day.date]?.[task];return `<label class="task-row ${done?'done':''}"><input type="checkbox" data-day-check="${day.date}" data-task="${task}" ${done?'checked':''}/><span><strong>${esc(label)}</strong><small>${esc(hint)}</small></span></label>`;}
function lessonMini(l,i){let done=!!state.progress.topics[l.id];return `<div class="lesson-mini"><button class="check-button ${done?'checked':''}" data-topic-toggle="${l.id}" title="${done?'Mark unfinished':'Mark mastered'}" aria-label="Toggle ${esc(l.title)}">${done?'✓':''}</button><div class="lesson-mini-body"><div class="lesson-mini-top">${badge(l.subject)}<span class="tiny muted">${String(i+1).padStart(2,'0')}</span></div><button class="lesson-title-btn" data-lesson="${l.id}">${esc(l.title)}</button><p>${esc(l.meaning)}</p></div><button class="mini-link" data-lesson="${l.id}">Study →</button></div>`;}
function recallEligible(){return lessons().filter(l=>state.progress.topics[l.id]||state.progress.recalls?.[l.id]);}
function recallDue(){return recallEligible().filter(l=>!state.progress.recalls?.[l.id]||state.progress.recalls[l.id].due_date<=state.serverDate);}
function flashDeck(){let arr=state.flashMode==='due'?recallDue():lessons();return arr.filter(l=>state.flashSub==='ALL'||l.subject===state.flashSub);}
function renderFlashcards(){const arr=flashDeck();state.flashIndex=Math.max(0,Math.min(state.flashIndex,arr.length-1));const l=arr[state.flashIndex];
 const select=`<div class="toolbar"><select class="select" id="flash-mode"><option value="due" ${state.flashMode==='due'?'selected':''}>Due / new mastered</option><option value="all" ${state.flashMode==='all'?'selected':''}>All ${lessons().length} concepts</option></select><select class="select" id="flash-sub"><option value="ALL">All subjects</option>${state.content.subjects.map(s=>`<option value="${s.id}" ${state.flashSub===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><span class="pill">${arr.length} in this deck</span></div>`;
 return `${heading('RETRIEVAL PRACTICE','Prove you understand it','Try to explain each concept before revealing the solution. Grade your recall to schedule your next review.')}${select}
 ${l?`<div class="flash-wrap"><div class="panel flash-card"><div class="flex between wrap gap-2 align-center"><span class="eyebrow">CARD ${state.flashIndex+1} OF ${arr.length}</span>${badge(l.subject)}</div><div class="flash-center"><span class="muted tiny">Without looking, answer in your own words</span><h2>${esc(l.title)}</h2><p>What does it mean? When would you use it? What is the core formula or fastest idea?</p></div>${state.flashRevealed?`<div class="flash-back"><span class="eyebrow">THE CORE IDEA</span><p><strong>${esc(l.meaning)}</strong></p><p>${esc(l.explanation)}</p><div class="formula">${esc(l.formula)}</div><div class="worked mt-2">${esc(l.worked)}</div><div class="tip good mt-2"><strong>Shortcut</strong>${esc(l.shortcut)}</div><div class="tip warn"><strong>Beware</strong>${esc(l.trap)}</div></div>`:`<button class="btn btn-primary w-full" data-flash-reveal="1">Reveal explanation & worked example</button>`}</div>
 ${state.flashRevealed?`<div class="panel panel-pad flash-rating"><span class="eyebrow">HOW WELL COULD YOU EXPLAIN IT?</span><div class="flex wrap gap-2 mt-2"><button class="btn btn-danger" data-flash-rate="again">Again · retry tomorrow</button><button class="btn btn-secondary" data-flash-rate="hard">Hard · revisit soon</button><button class="btn btn-secondary" data-flash-rate="good">Good · recall later</button><button class="btn btn-primary" data-flash-rate="easy">Easy · longer interval</button></div></div>`:''}
 <div class="flex between align-center mt-2"><button class="btn btn-secondary" data-flash-nav="prev" ${state.flashIndex===0?'disabled':''}>← Previous card</button><button class="btn btn-secondary" data-flash-nav="next" ${state.flashIndex===arr.length-1?'disabled':''}>Next card →</button></div></div>`:`<div class="panel empty-state"><h2>No flashcards due right now</h2><p>Master lessons to add them to the recall queue, or browse the complete deck.</p><button class="btn btn-primary" data-flash-all="1">Open all ${lessons().length} cards</button></div>`}
 <div class="info-strip mt-3">This uses interval-based review reminders stored in SQLite. It is a practical scheduling aid, not a guarantee of perfect long-term memory. Incorrect quiz answers become immediately due for review.</div>`;
}
function todayDefaultDay(){const here=state.content.days.find(d=>d.date===state.serverDate);return here||state.content.days.find(d=>d.date>state.serverDate)||state.content.days.at(-1);}
function renderToday(){let day=todayDefaultDay(),lessonList=(day.lesson_ids.length?day.lesson_ids:day.review_ids).map(lessonById),learnDone=completedTopics(),daysCompleted=days().filter(dayDone).length;
 let recent=state.progress.recent_attempts;let tested=recent.reduce((s,x)=>s+x.num_questions,0),right=recent.reduce((s,x)=>s+x.correct,0);
 const before=state.serverDate<state.content.meta.start;const after=state.serverDate>state.content.meta.end;
 return `<section class="hero"><div><span class="eyebrow">${before?'YOUR JOURNEY BEGINS TOMORROW':after?'YOUR ROADMAP IS COMPLETE':'YOUR STUDY DESK · '+fmtDate(day.date).toUpperCase()}</span><h1>${before?'89 days. One strong foundation.':after?'Keep the momentum going.':'Make today count. One concept at a time.'}</h1><p>Learn the meaning → work an example → solve under time → explain it without notes. Every check and quiz result is saved to your private study database.</p><button class="hero-action" data-day="${day.number}">Open day ${day.number} plan <span aria-hidden="true">↗</span></button></div><div class="hero-meta"><div class="hero-counter">${String(day.number).padStart(2,'0')}<span style="font-size:24px;color:#9ccec0">/89</span></div><p>YOUR CURRENT STUDY DAY</p><small>${fmtDate(day.date)}</small></div></section>
 <div class="stats-grid">${stat('Concepts mastered',`${learnDone} / ${lessons().length}`,`${percent(learnDone,lessons().length)}% of syllabus covered`)}${stat('Days completed',`${daysCompleted} / 89`,'Read · practice · recall')}${stat('Practice accuracy',tested?`${percent(right,tested)}%`:'—',tested?`${tested} questions attempted`:'Your first quiz starts here')}${stat('Learning streak',`${state.progress.streak} ${state.progress.streak===1?'day':'days'}`,'Recorded by the backend')}</div>
 <div class="two-col"><div><div class="section-heading"><div><h2>${before?'Tomorrow’s lesson plan':'Your learning today'}</h2><p>Day ${day.number} · ${fmtDate(day.date)} · ${day.phase}</p></div><button class="mini-link" data-day="${day.number}">View day details →</button></div><div class="panel panel-pad">${lessonList.map(lessonMini).join('')}</div></div><div class="right-stack"><div class="panel panel-pad"><div class="section-heading"><h2>Daily study ritual</h2><span class="pill">3 steps</span></div><p class="muted tiny">An effective session is more than reading. Finish these in order.</p><div class="task-list">${checklistTask(day,'read','Understand & write examples','Explain the concept in your own words')}${checklistTask(day,'practice','Solve GATE-style questions','Use marks and penalties to learn')}${checklistTask(day,'recall','Closed-book recall','Write formulas & mistakes from memory')}</div><button class="btn btn-primary w-full" data-daily-quiz="${day.number}">Start today’s practice ↗</button></div><div class="panel panel-pad"><span class="eyebrow">10-MINUTE DAILY HABIT</span><h3 style="margin:10px 0 6px">Never skip aptitude</h3><div class="habit-box">GATE General Aptitude contributes <strong>15 of 100 marks</strong>. Solve at least one verbal or quantitative question each study day, even when your technical topic is advanced.</div><button class="mini-link mt-2" data-practice-sub="GA">Practice GA →</button></div><div class="panel panel-pad"><span class="eyebrow">ACTIVE RECALL</span><h3 style="margin:8px 0">${recallDue().length} cards waiting</h3><p class="muted tiny">Explain mastered topics from memory. Incorrect quiz concepts reappear here automatically.</p><button class="btn btn-secondary w-full" data-view="flashcards">Open flashcard queue →</button></div><div class="info-strip">Training rule: get concepts right before getting faster. If you miss a question, open the related lesson and correct your notes.</div></div></div>`;
}
function renderRoadmap(){const options=['all','2026-11','2026-12','2027-01','2027-02'].map(m=>`<option value="${m}" ${state.month===m?'selected':''}>${{'all':'All dates','2026-11':'November 2026','2026-12':'December 2026','2027-01':'January 2027','2027-02':'February 2027'}[m]}</option>`).join('');
 const list=days().filter(d=>state.month==='all'||d.date.startsWith(state.month));let chunks=new Map();for(let d of list){let key=`Week ${d.week}`;if(!chunks.has(key))chunks.set(key,[]);chunks.get(key).push(d);}
 return `${heading('YOUR MASTER PLAN','89 days to exam readiness','A beginner-first path: foundational study → full syllabus → mixed practice → timed mocks → short final review.',`<div class="study-nav"><select class="select" id="month-filter" aria-label="Filter by month">${options}</select><button class="btn btn-secondary" data-day="${todayDefaultDay().number}">Go to current day</button></div>`)}<div class="panel panel-pad mb-2"><div class="flex between wrap align-center"><div><strong>5 Nov 2026 — 1 Feb 2027</strong><div class="muted tiny">56 lesson days · 27 revision days · 6 GATE-format mock sessions</div></div><span class="pill">${days().filter(dayDone).length} / 89 days checked</span></div>${progressBar(percent(days().filter(dayDone).length,89))}</div>
 ${[...chunks].map(([w,ds])=>`<section class="week-block"><div class="week-head"><h3>${w} <span class="muted tiny">· ${esc(ds[0].phase)}</span></h3><small>${fmtShort(ds[0].date)} – ${fmtShort(ds.at(-1).date)}</small></div><div class="study-plan-grid">${ds.map(d=>{let tasks=state.progress.day_tasks[d.date]||{};return `<button class="day-tile ${d.number===todayDefaultDay().number?'current':''} ${dayDone(d)?'completed':''}" data-day="${d.number}" title="${esc(d.title)}"><span class="date">${fmtShort(d.date)}</span><strong class="num">${d.number}</strong><span class="title">${esc(d.title)}</span><span class="dots">${['read','practice','recall'].map(t=>`<span class="${tasks[t]?'on':''}"></span>`).join('')}</span></button>`}).join('')}</div></section>`).join('')}`;
}
function renderDay(){const day=activeDay();const ls=(day.lesson_ids.length?day.lesson_ids:day.review_ids).map(lessonById);const choices=`<div class="study-nav"><button class="btn btn-secondary" data-day="${Math.max(1,day.number-1)}" ${day.number===1?'disabled':''}>← Previous</button><button class="btn btn-secondary" data-day="${Math.min(89,day.number+1)}" ${day.number===89?'disabled':''}>Next →</button></div>`;
 return `${heading(`DAY ${String(day.number).padStart(2,'0')} · ${fmtDate(day.date)}`,day.title,`${day.phase} · ${day.kind==='mock'?'65-question timed practice':'Core meaning, worked examples, formula recall and active testing'}`,choices)}<div class="two-col"><div><div class="section-heading"><h2>${day.kind==='learn'?'Learn these concepts':'Review these essential concepts'}</h2><span class="pill">${ls.length} topics</span></div><div class="panel panel-pad">${ls.map(lessonMini).join('')}</div><div class="panel panel-pad mt-2"><div class="section-heading"><h2>After you study</h2></div><p class="muted">${day.kind==='mock'?'Attempt this timed simulation. Inspect every incorrect answer, then write a one-sentence correction for each mistake.':'Solve today’s exam-style set. Work without looking at the explanation first; use the solution to repair incorrect reasoning.'}</p><button class="btn btn-primary" data-daily-quiz="${day.number}">${day.kind==='mock'?'Start 180-minute mock':'Start practice · '+day.question_ids.length+' questions'} →</button></div></div><div class="right-stack"><div class="panel panel-pad"><span class="eyebrow">THE DAILY CHECKLIST</span><h3 style="margin-top:7px">Mark only what you finished</h3><div class="task-list">${checklistTask(day,'read',day.kind==='learn'?'Lesson understanding':'Review & corrections','Read, derive, and explain')}${checklistTask(day,'practice','Timed practice','Submit a question set')}${checklistTask(day,'recall','Recall without notes','Formula and concept from memory')}</div><div class="label-line"><span>Session completion</span><strong>${percent(['read','practice','recall'].filter(t=>state.progress.day_tasks[day.date]?.[t]).length,3)}%</strong></div>${progressBar(percent(['read','practice','recall'].filter(t=>state.progress.day_tasks[day.date]?.[t]).length,3))}</div><div class="panel panel-pad"><span class="eyebrow">SUGGESTED STUDY BLOCK</span><h3 style="font-size:29px;margin:6px 0">${day.minutes} min</h3><div class="muted tiny">Approximate baseline; adjust to your available time.</div><div class="habit-box mt-2">40% understand + solve examples, 45% independent questions, 15% recall and mistakes. Add 10 minutes of daily aptitude.</div></div><div class="panel panel-pad"><h3>Exam mindset</h3><p class="muted tiny">MCQs: −⅓ for wrong 1-mark, −⅔ for wrong 2-mark. MSQ and NAT: no negative marking; MSQs do not award partial marks.</p></div></div></div>`;
}
function renderSyllabus(){const cards=state.content.subjects.map(s=>{const group=lessons().filter(l=>l.subject===s.id),done=group.filter(l=>state.progress.topics[l.id]).length,p=percent(done,group.length);return `<div class="panel subject-card"><div class="subject-card-top"><div class="subject-icon" style="background:${s.color}17;color:${s.color}">${s.id==='PDSA'?'PY':esc(s.id)}</div><div><h3>${esc(s.name)}</h3><p>${esc(s.subtitle)}</p></div></div><div class="subject-progress"><span>${done} / ${group.length} concepts</span><strong>${p}%</strong></div>${progressBar(p)}<div class="subject-actions"><span class="muted tiny">${group.length} concept lessons</span><button class="mini-link" data-subject="${s.id}">Explore lessons →</button></div></div>`}).join('');
 return `${heading('SYLLABUS LIBRARY','Master every building block','Every topic has detailed intuition, why the method works, two examples and a concept check. Search or study subject by subject.',`<button class="btn btn-secondary" data-view="roadmap">View daily schedule →</button>`)}<div class="toolbar"><input id="syllabus-search" class="search" placeholder="Search a topic, formula, or concept…" value="${esc(state.search)}" aria-label="Search topics" /></div>${state.search?renderSearchResults():`<div class="syllabus-cards">${cards}</div>`}`;
}
function renderSearchResults(){const q=state.search.trim().toLowerCase();const arr=lessons().filter(l=>[l.title,l.meaning,l.formula,l.explanation].join(' ').toLowerCase().includes(q));return `<div class="panel panel-pad"><h3>${arr.length} matching topics</h3>${arr.map((l,i)=>`<div class="syllabus-item"><button class="check-button ${state.progress.topics[l.id]?'checked':''}" data-topic-toggle="${l.id}">${state.progress.topics[l.id]?'✓':''}</button><div class="item-body">${badge(l.subject)} <button data-lesson="${l.id}">${esc(l.title)}</button><small>${esc(l.meaning)}</small></div></div>`).join('')||'<p class="muted">Try a different keyword.</p>'}</div>`;}
function renderSubject(){const s=subjectById(state.subject),ls=lessons().filter(l=>l.subject===state.subject),done=ls.filter(l=>state.progress.topics[l.id]).length;
 return `${heading('SUBJECT LIBRARY',s.name,s.subtitle,`<button class="btn btn-secondary" data-view="syllabus">← All subjects</button>`)}<div class="panel panel-pad mb-2"><div class="flex between"><strong>${done} of ${ls.length} topics mastered</strong><span class="pill">${subjectPercent(s.id)}%</span></div>${progressBar(subjectPercent(s.id))}</div><div class="panel panel-pad">${ls.map((l,i)=>`<div class="syllabus-item"><span class="number">${String(i+1).padStart(2,'0')}</span><button class="check-button ${state.progress.topics[l.id]?'checked':''}" data-topic-toggle="${l.id}" title="Toggle learned" aria-label="${esc(l.title)}">${state.progress.topics[l.id]?'✓':''}</button><div class="item-body"><button data-lesson="${l.id}">${esc(l.title)}</button><small>${esc(l.meaning)}</small></div><button class="mini-link" data-lesson="${l.id}">Open →</button></div>`).join('')}</div>`;
}
const LAB_FOR_SUB={PS:'bayes',LA:'matrix',CA:'calculus',ML:'gradient',PDSA:'graph',AI:'graph'};
// Safely format short emphasis/code spans in instructor-authored lesson steps.
const lessonRich=s=>esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');
function renderDiceMicro(){
 const target=state.diceSum??7;
 let n=0;
 const cells=Array.from({length:6},(_,i)=>Array.from({length:6},(_,j)=>{
   const hit=i+j+2===target;if(hit)n++;
   return `<span class="dice-cell ${hit?'hit':''}" title="Die 1: ${i+1}; die 2: ${j+1}">${i+1},${j+1}</span>`;
 }).join('')).join('');
 return `<div class="concept-micro-lab"><div class="flex between align-center wrap"><strong>Explore all 36 ordered outcomes</strong><span class="pill">Interactive experiment</span></div><p>Move the target sum and watch which of the 36 equally likely pairs are highlighted. The sums themselves are <strong>not</strong> equally likely.</p><label class="range-label" for="dice-sum">Target sum: <strong id="dice-target">${target}</strong></label><input type="range" min="2" max="12" step="1" value="${target}" id="dice-sum" class="micro-slider" aria-label="Target dice sum"><div class="dice-matrix" id="dice-grid">${cells}</div><div class="micro-result" id="dice-result">${n} favourable pairs out of 36 → probability <strong>${n}/36 ≈ ${(100*n/36).toFixed(1)}%</strong></div></div>`;
}
function renderPythonMicro(){
 const a=state.pyA??-7,b=state.pyB??3;
 const q=b===0?null:Math.floor(a/b),r=b===0?null:a-b*q;
 return `<div class="concept-micro-lab"><strong>Python operator simulator</strong><p>Change the operands and predict both results before reading the output. Python's // rounds down, including for negative numbers.</p><div class="micro-inputs"><label>Numerator a<input type="number" step="1" class="field" data-py-a="1" value="${a}"></label><label>Denominator b<input type="number" step="1" class="field" data-py-b="1" value="${b}"></label></div><div class="micro-result" id="python-results">${b===0?'Division by zero is undefined.':`a // b = <strong>${q}</strong> and a % b = <strong>${r}</strong>. Check: ${a} = ${b} × ${q} + ${r}.`}</div></div>`;
}
function renderLesson(){
 const l=lessonById(state.lesson);if(!l)return renderSyllabus();
 const s=subjectById(l.subject),list=lessons().filter(x=>x.subject===l.subject),idx=list.indexOf(l),d=l.deep;
 const mapped=qs().filter(q=>q.lesson_id===l.id),mastered=!!state.progress.topics[l.id];
 const daily=days().find(day=>day.lesson_ids.includes(l.id));
 const steps=(d?.solved_steps||[]).map((step,i)=>`<li><span class="step-number">${i===0?'Q':i}</span><span>${lessonRich(step)}</span></li>`).join('');
 const micro=l.id==='PS-001'?renderDiceMicro():l.id==='PDSA-001'?renderPythonMicro():'';
 return `${heading(`${s.name.toUpperCase()} / CONCEPT ${idx+1} OF ${list.length}`,'Detailed concept lesson','Learn the meaning first, understand why it works, then solve before revealing the answer.',`<button class="btn btn-secondary" data-subject="${l.subject}">← Subject list</button>`)}
 <div class="lesson-layout"><article class="lesson-article">
   <div class="flex between gap-2 wrap align-center">${badge(l.subject)}<span class="muted tiny">${daily?'Scheduled on '+fmtDate(daily.date):'Revision-ready topic'} · Detailed edition</span></div>
   <h1 style="margin:17px 0 15px">${esc(l.title)}</h1>
   <p class="lead">${esc(l.meaning)}</p>
   <div class="learning-route"><strong>How to study this concept</strong><span>Understand → See why → Follow an example → Solve a new example → Check yourself</span></div>
   <section class="lesson-block"><span class="block-label">01 / First principles</span><h2>Build the mental picture</h2><p>${esc(d.intuition)}</p></section>
   <section class="lesson-block"><span class="block-label">02 / The deeper explanation</span><h2>How it works — and why</h2><p>${esc(l.explanation)}</p><p>${esc(d.reasoning)}</p></section>
   <section class="lesson-block"><span class="block-label">03 / Formula and conditions</span><h2>Connect the idea to the maths</h2><div class="formula">${esc(l.formula)}</div><p class="formula-guidance">Pause here: identify what each quantity represents, the assumptions you need, and the units or possible values of the answer.</p></section>
   <section class="lesson-block"><span class="block-label">04 / First worked example</span><h2>See the rule in action</h2><div class="worked">${esc(l.worked)}</div></section>
   <section class="lesson-block"><span class="block-label">05 / A second example with reasoning</span><h2>Follow each decision</h2><ol class="worked-steps">${steps}</ol></section>
   ${micro?`<section class="lesson-block"><span class="block-label">06 / Interactive understanding</span><h2>Change the inputs, observe the effect</h2>${micro}</section>`:''}
   <section class="lesson-block"><span class="block-label">${micro?'07':'06'} / Test your understanding</span><h2>Predict before revealing</h2><div class="concept-check"><p class="concept-question">${esc(d.check_question)}</p><button class="btn btn-secondary" data-reveal-check="1" aria-controls="concept-check-answer" aria-expanded="false">Reveal the explanation</button><div id="concept-check-answer" class="concept-answer" hidden>${esc(d.check_answer)}</div></div><p class="tiny muted">Write your answer first. This is a learning check, not an automatically scored quiz; the related exam questions are graded by the backend.</p></section>
   <section class="lesson-block"><span class="block-label">${micro?'08':'07'} / GATE speed toolkit</span><h2>Choose the right method in the exam</h2><div class="tip good"><strong>⚡ Fast recognition</strong>${esc(l.shortcut)}</div><div class="tip warn"><strong>! Common exam trap</strong>${esc(l.trap)}</div></section>
   <div class="lesson-bottom-actions"><button class="btn ${mastered?'btn-secondary':'btn-primary'}" data-topic-toggle="${l.id}">${mastered?'✓ Mastered · undo':'✓ Mark concept mastered'}</button>${mapped.length?`<button class="btn btn-secondary" data-topic-quiz="${l.id}">Solve ${mapped.length} related question${mapped.length>1?'s':''}</button>`:''}${LAB_FOR_SUB[l.subject]?`<button class="btn btn-secondary" data-lab="${LAB_FOR_SUB[l.subject]}">Open visual lab ↗</button>`:''}</div>
   <div class="lesson-bottom-actions"><button class="mini-link" ${idx===0?'disabled':''} data-lesson="${idx>0?list[idx-1].id:''}">← Previous concept</button><button class="mini-link" ${idx===list.length-1?'disabled':''} data-lesson="${idx<list.length-1?list[idx+1].id:''}">Next concept →</button></div>
 </article><aside class="lesson-aside"><div class="panel panel-pad"><span class="eyebrow">ACTIVE LEARNING</span><h3 style="margin:8px 0">Try this without notes</h3><p class="muted tiny">1. Explain the idea in plain language.<br>2. State when its formula applies.<br>3. Work through the second problem on paper.<br>4. Answer the prediction check.</p><div class="info-strip">Only mark a concept mastered when you can reproduce the reasoning, not just recognize the final answer.</div></div>
 <div class="panel panel-pad"><h3>Your own notes</h3><p class="muted tiny">Write what you learned or which step confused you. Notes are stored in the SQLite backend.</p><textarea class="note-area" id="lesson-note" placeholder="My understanding in simple words…">${esc(state.progress.notes[l.id]||'')}</textarea><button class="btn btn-primary mt-2" data-save-note="${l.id}">Save note</button></div>
 <div class="panel panel-pad"><h3>Exam practice</h3><p class="tiny muted">${mapped.length} related scored question${mapped.length===1?'':'s'}; review the provided solutions and revisit missed concepts.</p>${mapped.length?`<button class="mini-link" data-topic-quiz="${l.id}">Start graded question →</button>`:''}</div></aside></div>`;
}
function renderPractice(){const history=state.progress.recent_attempts.slice(0,4);return `${heading('EXAM PRACTICE','Learn by solving','Original GATE-style MCQ, MSQ and NAT questions with backend grading and worked explanations.')}
 <div class="practice-cards"><div class="panel practice-card"><span class="big-symbol">◉</span><h3>Daily drill</h3><p>Practice the topics on your current schedule with short, mixed question sets.</p><button class="btn btn-primary w-full" data-daily-quiz="${todayDefaultDay().number}">Start daily set →</button></div><div class="panel practice-card"><span class="big-symbol">∑</span><h3>Custom subject drill</h3><p>Choose a subject, question count and difficulty. Review detailed solutions afterwards.</p><button class="btn btn-secondary w-full" data-start-custom="1">Start custom set →</button></div><div class="panel practice-card"><span class="big-symbol">◷</span><h3>180-minute simulation</h3><p>65 original questions, GATE-style answer formats, a countdown timer and exam-like penalties.</p><button class="btn btn-secondary w-full" data-start-mock="1">Start full mock →</button></div></div>
 <div class="panel panel-pad mt-2"><h3>Custom drill controls</h3><div class="toolbar" style="margin:10px 0"><label class="muted tiny">Subject<br><select class="select" id="practice-sub">${`<option value="ALL">All subjects</option>`+state.content.subjects.map(s=>`<option value="${s.id}" ${state.practiceSub===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="muted tiny">Questions<br><select class="select" id="practice-count">${[5,10,15,20,30].map(n=>`<option ${state.practiceCount===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="muted tiny">Difficulty<br><select class="select" id="practice-difficulty">${[['all','Mixed'],['foundation','Foundation'],['standard','Standard'],['tricky','Challenging']].map(([v,n])=>`<option value="${v}" ${state.practiceDifficulty===v?'selected':''}>${n}</option>`).join('')}</select></label></div><button class="btn btn-primary" data-start-custom="1">Generate & start drill</button></div>
 <div class="panel panel-pad mt-2"><div class="section-heading"><h2>Recent attempts</h2><button class="mini-link" data-view="insights">All performance →</button></div>${history.length?history.map(r=>`<div class="history-item"><div><strong>${esc(r.label||'Practice set')}</strong><div class="muted tiny">${fmtShort(r.timestamp.slice(0,10))} · ${r.num_questions} questions</div></div><div class="text-right"><strong>${r.correct}/${r.num_questions} correct</strong><div class="muted tiny">${r.score} / ${r.max_score} marks</div></div></div>`).join(''):`<p class="muted tiny">Your scores will appear here after your first submitted quiz.</p>`}</div>
 <div class="panel panel-pad mt-2"><div class="section-heading"><h2>Previous-year papers · official source</h2></div><p class="muted tiny">After mastering the fundamentals, solve actual GATE DA papers from 2024–2026 and compare with the official answer keys. These PDFs need an Internet connection.</p><a href="https://gate2027.iitm.ac.in/download" target="_blank" rel="noopener">Open IIT Madras official papers and answer keys ↗</a></div><div class="info-strip mt-2">The questions are original GATE-style practice, not official previous-year questions. Full mock sessions use 65 questions, a 180-minute timer, 100 available marks, 15 GA marks and 85 DA marks. Their difficulty is illustrative, not a prediction of exam questions.</div>`;
}
function startQuiz(ids,label,day=null,mock=false){let selected=[...new Set(ids)].filter(id=>qById(id));if(!selected.length){toast('There are no questions in this selection.');return;}clearInterval(timerInterval);state.quiz={ids:selected,index:0,answers:{},label,day,mock,endsAt:mock?Date.now()+180*60*1000:null};state.result=null;goto('quiz');}
function launchDaily(n){const d=dayByNumber(Number(n));startQuiz(d.question_ids,d.kind==='mock'?d.title:`Day ${d.number} · practice`,d.date,d.kind==='mock');}
function seededShuffle(xs,seed){let out=[...xs],a=seed>>>0;for(let i=out.length-1;i>0;i--){a=(a*1664525+1013904223)>>>0;const j=a%(i+1);[out[i],out[j]]=[out[j],out[i]];}return out;}
function launchCustom(){let sub=state.practiceSub,diff=state.practiceDifficulty;let pool=qs().filter(q=>(sub==='ALL'||q.subject===sub)&&(diff==='all'||q.difficulty===diff));if(!pool.length){toast('No questions match these filters');return;}const ids=seededShuffle(pool.map(x=>x.id),Math.round(Date.now()/60000)).slice(0,state.practiceCount);startQuiz(ids,sub==='ALL'?'Mixed subject drill':`${subjectById(sub).name} drill`);}
function launchMock(){const d=days().find(x=>x.kind==='mock')||days()[70];startQuiz(d.question_ids,'65-question GATE-format practice',d.date,true);}
function displayAnswer(answer,q){if(answer===undefined||answer===null||answer==='')return 'Not answered';if(q.type==='NAT')return String(answer);if(q.type==='MSQ')return answer.map(i=>String.fromCharCode(65+i)).join(', ')||'No option selected';return String.fromCharCode(65+Number(answer));}
function renderQuiz(){const quiz=state.quiz;if(!quiz)return renderPractice();let q=qById(quiz.ids[quiz.index]);let ans=quiz.answers[q.id];let count=quiz.ids.filter(id=>quiz.answers[id]!==undefined&&quiz.answers[id]!==null&&quiz.answers[id]!==''&&(qById(id).type!=='MSQ'||quiz.answers[id].length)).length;
 const choiceHtml=q.type==='NAT'?`<label class="muted tiny">Enter a numerical answer (decimal accepted)</label><input class="field w-100" id="nat-answer" inputmode="decimal" type="number" step="any" placeholder="Type your numerical answer" value="${esc(ans??'')}" style="font-size:19px;padding:15px;margin-top:11px"/>`:
 `<div class="choices">${q.options.map((option,i)=>{let chosen=q.type==='MSQ'?Array.isArray(ans)&&ans.includes(i):ans===i;return `<button class="choice ${chosen?'selected':''}" data-option="${i}" aria-pressed="${chosen}"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(option.trim())}</span></button>`}).join('')}</div>`;
 return `<div class="quiz-shell"><div class="quiz-header"><div><span class="eyebrow">${esc(quiz.label)} · ${quiz.mock?'180 MIN EXAM MODE':'LEARNING MODE'}</span><h1>Question ${quiz.index+1} of ${quiz.ids.length}</h1><span class="muted tiny">${count} answered · ${quiz.ids.length-count} remaining</span></div><div class="flex gap-2 align-center"><span id="quiz-timer" class="timer ${quiz.mock?'':'hidden'}">03:00:00</span><button class="btn btn-secondary" data-quiz-exit="1">Exit</button></div></div>${progressBar(percent(count,quiz.ids.length))}<div class="question-pager">${quiz.ids.map((id,i)=>`<button class="page-dot ${i===quiz.index?'active':''} ${quiz.answers[id]!==undefined&&quiz.answers[id]!==''?'answered':''}" data-q-index="${i}" title="Question ${i+1}">${i+1}</button>`).join('')}</div>
 <div class="question-card"><div class="question-top"><div>${badge(q.subject)} <span class="pill">${esc(q.type)}</span> <span class="pill">${q.marks} mark${q.marks>1?'s':''}</span></div><span class="muted">${esc(q.difficulty)} · ${esc(q.type==='MSQ'?'Select every correct choice':q.type==='NAT'?'Numerical response':'Choose one answer')}</span></div><div class="question-prompt">${esc(q.prompt)}</div>${choiceHtml}<div class="question-foot"><button class="btn btn-secondary" data-q-prev="1" ${quiz.index===0?'disabled':''}>← Previous</button><div class="flex gap-2">${quiz.index<quiz.ids.length-1?`<button class="btn btn-primary" data-q-next="1">Next question →</button>`:`<button class="btn btn-primary" data-quiz-submit="1">Submit & review →</button>`}</div></div></div><div class="flex between wrap mt-2" style="gap:10px"><span class="muted tiny">${quiz.mock?'Timer runs until submission.':'Take your time to reason before submitting.'} No solution is revealed until submission.</span><button class="mini-link" data-quiz-submit="1">Finish ${quiz.ids.length}-question set</button></div></div>`;
}
function startTimer(){clearInterval(timerInterval);if(!state.quiz?.mock)return;const tick=()=>{if(state.view!=='quiz'||!state.quiz)return clearInterval(timerInterval);let secs=Math.max(0,Math.ceil((state.quiz.endsAt-Date.now())/1000));let t=$('#quiz-timer');if(t){t.textContent=[Math.floor(secs/3600),Math.floor(secs%3600/60),secs%60].map(x=>String(x).padStart(2,'0')).join(':');t.classList.toggle('danger',secs<600);}if(secs===0){clearInterval(timerInterval);submitQuiz(true);}};tick();timerInterval=setInterval(tick,1000);}
async function submitQuiz(auto=false){const quiz=state.quiz;if(!quiz)return;if(!auto&&!confirm(`Submit ${quiz.ids.length} questions now? You have answered ${Object.keys(quiz.answers).filter(k=>quiz.answers[k]!==''&&quiz.answers[k]!==null).length}.`))return;
 try{clearInterval(timerInterval);let answers=Object.fromEntries(quiz.ids.map(id=>[id,quiz.answers[id]??null]));let result=await api('/api/quiz',{answers,day:quiz.day,label:quiz.label});state.result=result;state.progress.recent_attempts.unshift({id:result.attempt_id,label:quiz.label,day:quiz.day,num_questions:quiz.ids.length,correct:result.correct,score:result.score,max_score:result.max_score,timestamp:new Date().toISOString()});if(quiz.day){state.progress.day_tasks[quiz.day]??={};state.progress.day_tasks[quiz.day].practice=true;await api('/api/day',{day:quiz.day,task:'practice',completed:true});}const updated=await api('/api/bootstrap');state.progress=updated.progress;goto('result');toast('Attempt saved to your progress database.');}catch(e){toast('Could not submit: '+e.message);}}
function renderResult(){const r=state.result;if(!r)return renderPractice();let q=state.quiz;return `<div class="quiz-shell">${heading('EXAM PRACTICE / ANSWER REVIEW','Your result is ready','Every mistake is an opportunity to repair a concept, not just a number.',`<button class="btn btn-secondary" data-view="practice">Back to practice</button>`)}<div class="result-score"><div><div class="muted" style="color:#bdd8cc">EXAM-STYLE MARKING</div><div class="value">${r.score} <span style="font-size:15px">/ ${r.max_score}</span></div><p>${r.correct} of ${r.results.length} correct · ${percent(r.correct,r.results.length)}% accuracy</p></div><span style="font-size:30px">${r.correct/r.results.length>=.8?'✓':'↗'}</span></div><div class="info-strip mt-2">MCQ wrong answers carry a penalty of one-third of question marks. MSQ and NAT wrong answers are scored zero. Examine explanations before retrying.</div><div class="section-heading mt-3"><h2>Question-by-question solutions</h2><button class="mini-link" data-view="practice">New practice →</button></div>${r.results.map((item,i)=>{const qq=qById(item.id);return `<div class="answer-review"><div class="flex between gap-2 wrap align-center"><span class="${item.correct?'correct-tag':'wrong-tag'}">${item.correct?'✓ Correct':item.answered?'✕ Incorrect':'○ Skipped'} · ${item.awarded} mark${item.awarded===1?'':'s'}</span>${badge(item.subject)}</div><div class="answer-title" style="margin-top:9px">${i+1}. ${esc(item.prompt)}</div><div class="muted tiny">Your answer: <strong>${esc(displayAnswer(item.your_answer,qq))}</strong> · Correct: <strong>${esc(displayAnswer(item.correct_answer,qq))}</strong></div><p>${esc(item.solution)}</p><div class="mt-1"><button class="mini-link" data-lesson="${item.lesson_id}">Review related concept →</button></div></div>`}).join('')}<div class="mt-3"><button class="btn btn-primary" data-view="practice">Continue practicing →</button></div></div>`;}
function renderInsights(){const done=completedTopics();const attempts=state.progress.recent_attempts;const sorted=state.content.subjects.map(s=>({s,acc:state.progress.subject_accuracy[s.id]})).sort((a,b)=>{const x=a.acc?.attempted?a.acc.right/a.acc.attempted:1;const y=b.acc?.attempted?b.acc.right/b.acc.attempted:1;return x-y;});const weak=sorted.filter(x=>x.acc?.attempted).slice(0,3);
 return `${heading('PROGRESS & RETENTION','Know what to revise','The goal is long-term recall, not simply checking boxes. Use accuracy to choose your next session.')}
 <div class="stats-grid">${stat('Lessons checked',done,`of ${lessons().length} topics`)}${stat('Complete days',days().filter(dayDone).length,'out of 89')}${stat('Practice attempts',attempts.length,'recent 30 listed')}${stat('Current streak',state.progress.streak,'days with saved activity')}</div><div class="insights-grid"><div class="panel panel-pad"><div class="section-heading"><h2>Syllabus mastery</h2><span class="pill">${percent(done,lessons().length)}% total</span></div>${state.content.subjects.map(s=>{let n=subjectPercent(s.id);return `<div class="subject-bar-row"><span>${esc(s.name)}</span>${progressBar(n)}<strong class="text-right">${n}%</strong></div>`}).join('')}</div><div class="panel panel-pad"><div class="section-heading"><h2>Weak-subject radar</h2></div>${weak.length?weak.map(({s,acc})=>`<div class="lesson-mini"><div class="lesson-mini-body">${badge(s.id)} <strong>${esc(s.name)}</strong><p>Accuracy ${percent(acc.right,acc.attempted)}% across ${acc.attempted} answered questions.</p></div><button class="mini-link" data-practice-sub="${s.id}">Drill →</button></div>`).join(''):'<p class="muted">Submit a quiz to see which subjects need extra attention.</p>'}<div class="info-strip mt-2">A low accuracy percentage from only a few questions is a signal for review, not a final judgment of your ability.</div></div></div><div class="panel panel-pad mt-2"><div class="section-heading"><h2>Attempt history</h2></div>${attempts.length?attempts.map(r=>`<div class="history-item"><div><strong>${esc(r.label||'Practice')}</strong><div class="muted tiny">${esc(r.timestamp.slice(0,16).replace('T',' '))} · ${r.num_questions} questions</div></div><div class="text-right"><strong>${r.correct} / ${r.num_questions}</strong><div class="muted tiny">${r.score} / ${r.max_score} marks</div></div></div>`).join(''):'<div class="empty-state">No attempts yet. Your first practice set unlocks performance tracking.</div>'}</div>`;
}
function renderSettings(){const mins=state.progress.settings.daily_minutes||'150';return `${heading('YOUR ACCOUNT & PREFERENCES','Keep your study data safe','Your own checklists, notes, quiz results and flashcards are saved to your account on this server.')}
 <div class="settings-grid"><div class="panel panel-pad"><span class="eyebrow">STUDY TARGET</span><h3 style="margin:10px 0">Daily study time</h3><p class="muted tiny">Adjust the personal target. The roadmap’s suggested durations remain unchanged.</p><div class="flex gap-2 align-center"><input class="field" id="daily-minutes" type="number" min="45" max="480" step="15" value="${esc(mins)}" style="max-width:160px"/><span class="muted">minutes/day</span><button class="btn btn-primary" data-save-minutes="1">Save</button></div><div class="callout mt-3">Study in 40–50 minute focus blocks, followed by a short break. Quality of recall matters more than the clock.</div></div><div class="panel panel-pad"><span class="eyebrow">YOUR DATA</span><h3 style="margin:10px 0">Export or restore</h3><p class="muted tiny">Download a JSON backup with completed topics, daily tasks, notes and practice history.</p><div class="flex gap-2 wrap"><button class="btn btn-primary" data-export="1">Download backup</button><button class="btn btn-secondary" data-import-open="1">Restore backup</button><input id="import-file" type="file" accept=".json,application/json" class="hidden"/></div><div class="callout mt-3">Your personal export restores only into the account you are signed in to. Import replaces only your own progress.</div></div><div class="panel panel-pad"><span class="eyebrow">ACCOUNT SECURITY</span><h3 style="margin:10px 0">Change password</h3><p class="muted tiny">Update your password without affecting other learners. Other sessions on your account will be signed out.</p><form id="change-password-form" class="password-settings"><input class="field" type="password" id="old-password" autocomplete="current-password" placeholder="Current password" required/><input class="field" type="password" id="new-password" autocomplete="new-password" placeholder="New password (10+ characters)" minlength="10" required/><button class="btn btn-primary" type="submit">Update password</button></form></div><div class="panel panel-pad"><span class="eyebrow">CONTENT & SOURCES</span><h3 style="margin:10px 0">Official syllabus mapping</h3><p class="muted tiny">The lessons follow the official 2027 IIT Madras DA syllabus and official GA syllabus, with a dated plan and original practice.</p><div class="flex wrap gap-2"><a href="${state.content.meta.source_da}" target="_blank" rel="noopener">DA syllabus ↗</a><a href="${state.content.meta.source_ga}" target="_blank" rel="noopener">GA syllabus ↗</a><a href="${state.content.meta.source_pattern}" target="_blank" rel="noopener">Question pattern ↗</a></div></div><div class="panel panel-pad"><span class="eyebrow">DANGER ZONE</span><h3 style="margin:10px 0">Reset all progress</h3><p class="muted tiny">Deletes your checkboxes, notes and quiz attempts. Consider downloading a backup first.</p><button class="btn btn-danger" data-reset="1">Reset my saved progress</button></div></div>`;
}
function renderLabs(){const tabs=[['bayes','Bayes intuition'],['matrix','Matrix transformation'],['calculus','Tangent & derivative'],['gradient','Gradient descent'],['graph','BFS vs DFS']];const descriptions={bayes:['Why a positive test can still be misleading','Change prevalence and test accuracy to see how prior probability transforms a test result.'],matrix:['A matrix literally moves space','Drag matrix entries to see basis vectors and a unit square transformed.'],calculus:['Derivative is the slope of a moving tangent','Move along a curve to see the exact slope, curvature and stationary point.'],gradient:['Optimization is a repeated decision','Change the learning rate and see when descent converges or overshoots.'],graph:['Search order changes exploration','Step through BFS and DFS to learn what queues and stacks actually do.']};let desc=descriptions[state.lab];return `${heading('INTERACTIVE UNDERSTANDING','Concept labs','Move controls, predict what happens, and test your explanation against the visual result.')}
 <div class="lab-tabs">${tabs.map(([id,n])=>`<button class="tab ${state.lab===id?'active':''}" data-lab="${id}">${n}</button>`).join('')}</div><div class="panel panel-pad mb-2"><span class="eyebrow">EXPLORE BY CHANGING ONE THING</span><h2 style="margin:8px 0">${esc(desc[0])}</h2><p class="muted" style="margin:0">${esc(desc[1])}</p></div><div class="lab-layout"><div class="lab-canvas" id="lab-visual" aria-label="Interactive concept visualization"></div><div class="panel lab-controls"><div id="lab-control-body">${controlsForLab()}</div><div id="lab-values"></div></div></div><div class="lab-hint"><strong>Active learning:</strong> first predict the change, then move the control, then explain the result. Repeating this is more effective than memorizing one formula.</div>`;}
function range(key,label,min,max,step,unit=''){return `<div class="range-control"><label for="range-${key}"><span>${esc(label)}</span><strong id="label-${key}">${state.labParams[key]}${unit}</strong></label><input id="range-${key}" data-range="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${state.labParams[key]}" aria-label="${esc(label)}" /></div>`;}
function controlsForLab(){const p=state.labParams;switch(state.lab){case 'bayes':return `${range('prev','Prevalence',1,50,1,'%')}${range('sens','Sensitivity',50,100,1,'%')}${range('fpr','False-positive rate',1,40,1,'%')}<p class="lab-story">Imagine testing 10,000 people. Notice how false positives can dominate when the condition is rare.</p>`;case 'matrix':return `<div class="lab-story mb-2"><strong>Matrix A = [[a,b],[c,d]]</strong>. Columns show where basis arrows e₁ and e₂ move.</div>${range('a','a (x of first basis)',-2,2,.25)}${range('b','b (x of second basis)',-2,2,.25)}${range('c','c (y of first basis)',-2,2,.25)}${range('d','d (y of second basis)',-2,2,.25)}`;case 'calculus':return `${range('x','Position x',-1,5,.1)}<p class="lab-story">At each point, the green tangent shows the instantaneous direction and rate of change. Where slope is zero the curve is locally flat.</p>`;case 'gradient':return `${range('lr','Learning rate η',.05,1.2,.05)}${range('steps','Number of steps',1,12,1)}<p class="lab-story">Objective: minimize f(x)=(x−3)², starting from x=−1. A step greater than 1 can become unstable.</p>`;case 'graph':return `<div class="lab-story"><strong>Choose the frontier rule</strong></div><div class="flex gap-2 mt-2"><button class="tab ${p.alg==='BFS'?'active':''}" data-alg="BFS">BFS · queue</button><button class="tab ${p.alg==='DFS'?'active':''}" data-alg="DFS">DFS · stack</button></div><div class="mt-3 flex gap-2"><button class="btn btn-primary" data-step="1">Next step →</button><button class="btn btn-secondary" data-step-reset="1">Reset</button></div><p class="lab-story mt-3">BFS explores level by level and finds shortest routes in an unweighted graph. DFS commits to depth before backtracking.</p>`;default:return '';}}
const svgHeader=`<svg viewBox="0 0 520 340" role="img" aria-label="Mathematical concept visualization" xmlns="http://www.w3.org/2000/svg">`;
function line(x1,y1,x2,y2,color='#dce6e2',width=1,extra=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}" ${extra}/>`;}
function labDraw(){const p=state.labParams;let svg='',values='';
 if(state.lab==='bayes'){let sick=100*p.prev,healthy=10000-sick,tp=Math.round(sick*p.sens/100),fp=Math.round(healthy*p.fpr/100),tot=tp+fp,post=100*tp/(tot||1);let goodWidth=tot?400*tp/tot:0;
 svg=svgHeader+`<text x="50" y="40" font-size="14" fill="#315f54" font-weight="700">Among ${tot.toLocaleString('en-IN')} positive tests</text><rect x="50" y="68" width="400" height="52" rx="9" fill="#f5d9d4"/><rect x="50" y="68" width="${goodWidth}" height="52" rx="9" fill="#3e9d81"/><text x="50" y="150" font-size="12" fill="#3d6159">True positives ${tp.toLocaleString('en-IN')} · False positives ${fp.toLocaleString('en-IN')}</text><text x="50" y="199" font-size="12" fill="#71817b">Green = condition present + positive test</text><text x="50" y="222" font-size="12" fill="#71817b">Pink = condition absent + positive test</text><text x="50" y="280" font-size="16" font-weight="800" fill="#204e42">Posterior = ${post.toFixed(1)}%</text></svg>`;
 values=`<div class="metric-highlight"><small>Probability condition is present after a + result</small><strong>${post.toFixed(1)}%</strong><small>${tp} / (${tp} + ${fp}) positive tests</small></div><p class="lab-story mt-2">Even a ${p.sens}% sensitive test can have a modest positive predictive value when prevalence is low. That is Bayes' theorem in action.</p>`;
 } else if(state.lab==='matrix'){let ox=260,oy=176,k=62;let grid='';for(let i=-4;i<=4;i++){grid+=line(ox+i*k,8,ox+i*k,332,i===0?'#b9cfc4':'#eef1ee',i===0?2:1);grid+=line(8,oy+i*k,512,oy+i*k,i===0?'#b9cfc4':'#eef1ee',i===0?2:1);}
 const x1=ox+p.a*k,y1=oy-p.c*k,x2=ox+p.b*k,y2=oy-p.d*k,x3=ox+(p.a+p.b)*k,y3=oy-(p.c+p.d)*k;const det=p.a*p.d-p.b*p.c;
 svg=svgHeader+grid+`<polygon points="${ox},${oy} ${x1},${y1} ${x3},${y3} ${x2},${y2}" fill="#b9dfd4" fill-opacity=".60" stroke="#268d7c" stroke-width="2"/>${line(ox,oy,x1,y1,'#276eb6',4)}${line(ox,oy,x2,y2,'#b87932',4)}<circle cx="${x1}" cy="${y1}" r="5" fill="#276eb6"/><circle cx="${x2}" cy="${y2}" r="5" fill="#b87932"/><text x="${x1+8}" y="${y1-7}" fill="#276eb6" font-size="13">A e₁</text><text x="${x2+8}" y="${y2-7}" fill="#b87932" font-size="13">A e₂</text><text x="20" y="24" font-size="12" fill="#5c776e">Transformed unit square and basis vectors</text></svg>`;
 values=`<div class="metric-highlight"><small>Area scale / oriented determinant</small><strong>${det.toFixed(2)}</strong><small>det(A) = ad − bc</small></div><p class="lab-story mt-2">Absolute determinant scales area. Zero collapses the square into a line or point: the matrix loses invertibility. Negative determinant reverses orientation.</p>`;
 } else if(state.lab==='calculus'){let plot=x=>({x:40+(x+1)/6*440,y:284-((x*x-4*x+3+2)/17)*230});let pts=[];for(let i=0;i<=120;i++){let x=-1+i/20;let o=plot(x);pts.push(`${o.x.toFixed(1)},${o.y.toFixed(1)}`);}let x=Number(p.x),y=x*x-4*x+3,m=2*x-4;let p0=plot(x),t1=plot(x-1.5),t2=plot(x+1.5);t1.y=plot(x).y+(-m*1.5)*(-230/17);t2.y=plot(x).y+(m*1.5)*(-230/17);
 svg=svgHeader+`<rect x="38" y="28" width="450" height="264" rx="10" fill="#fbfdfc" stroke="#edf1ef"/>${line(40,284,490,284,'#aebeb8',1.5)}${line(114,28,114,296,'#aebeb8',1.5)}<polyline points="${pts.join(' ')}" fill="none" stroke="#2d8b7f" stroke-width="4" stroke-linejoin="round"/>${line(t1.x,t1.y,t2.x,t2.y,'#c47a43',3,'stroke-dasharray="6 4"')}<circle cx="${p0.x}" cy="${p0.y}" r="6" fill="#164b42" stroke="#fff" stroke-width="2"/><text x="52" y="47" font-size="13" fill="#67857a">f(x) = x² − 4x + 3</text></svg>`;
 values=`<div class="metric-highlight"><small>Instantaneous derivative f'(x)</small><strong>${m.toFixed(2)}</strong><small>At x = ${x.toFixed(1)}, f(x) = ${y.toFixed(2)}</small></div><p class="lab-story mt-2">${m>0?'Positive slope: the function increases as x moves right.':m<0?'Negative slope: the function decreases as x moves right.':'Zero slope: stationary point at x=2. The curve has a minimum here.'}</p>`;
 } else if(state.lab==='gradient'){let x=-1,steps=[x],diverge=false;for(let i=0;i<p.steps;i++){x=x-Number(p.lr)*2*(x-3);steps.push(x);if(Math.abs(x)>25)diverge=true;}
 let plot=x=>({x:50+((x+2)/10)*425,y:297-Math.min(240,((x-3)**2)*10)});
 let curve=[];for(let i=0;i<=100;i++){let xx=-2+i*.1,o=plot(xx);curve.push(`${o.x.toFixed(1)},${o.y.toFixed(1)}`)};
 svg=svgHeader+`<rect x="36" y="28" width="449" height="280" rx="10" fill="#fbfdfc" stroke="#edf1ef"/>${line(35,297,490,297,'#b9c8c1')}<polyline points="${curve.join(' ')}" fill="none" stroke="#2c8f7c" stroke-width="3"/>${steps.map((xx,i)=>{let pp=plot(Math.max(-2,Math.min(8,xx)));return `<circle cx="${pp.x}" cy="${pp.y}" r="${i===steps.length-1?7:4}" fill="${i===steps.length-1?'#ca7643':'#305b9c'}" stroke="white" stroke-width="1"/><text x="${pp.x+7}" y="${pp.y-7}" font-size="10" fill="#486765">${i}</text>`}).join('')}<text x="43" y="48" font-size="13" fill="#638477">f(x)=(x−3)² · minimum at x=3</text></svg>`;
 values=`<div class="metric-highlight"><small>Parameter after ${p.steps} steps</small><strong>${Math.abs(x)>999?'Out of range':x.toFixed(3)}</strong><small>Loss = ${Math.pow(x-3,2).toFixed(3)}</small></div><p class="lab-story mt-2">${p.lr>1?'Learning rate is unstable: the updates expand the distance from 3.':p.lr===1?'At η=1, the update oscillates symmetrically for this quadratic.':'As the estimate approaches x=3 the gradient shrinks. A reasonable learning rate gives convergence.'}</p>`;
 } else if(state.lab==='graph'){const positions={A:[85,55],B:[190,120],C:[390,120],D:[105,245],E:[245,245],F:[400,245],G:[320,305]},edges=[['A','B'],['A','C'],['B','D'],['B','E'],['C','F'],['E','G'],['F','G']];
 function order(alg){let vis=[],seen=new Set(),front=['A'];while(front.length){let v=alg==='BFS'?front.shift():front.pop();if(seen.has(v))continue;seen.add(v);vis.push(v);let neigh=edges.flatMap(([a,b])=>a===v?[b]:b===v?[a]:[]).filter(z=>!seen.has(z)).sort();if(alg==='DFS')neigh.reverse();for(let w of neigh)front.push(w);}return vis;}
 let visited=order(p.alg).slice(0,p.step),next=order(p.alg)[p.step]||null;
 svg=svgHeader+edges.map(([a,b])=>line(positions[a][0],positions[a][1],positions[b][0],positions[b][1],'#bdcbc4',3)).join('')+Object.keys(positions).map(n=>{let [x,y]=positions[n],done=visited.includes(n),current=n===next;return `<circle cx="${x}" cy="${y}" r="23" fill="${done?'#247e70':current?'#e7b46c':'#e7efeb'}" stroke="${current?'#b77d2e':'#c8dbd1'}" stroke-width="2"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="15" font-weight="800" fill="${done?'#fff':'#34544a'}">${n}</text>`}).join('')+`</svg>`;
 values=`<div class="metric-highlight"><small>Visited with ${p.alg} (${visited.length} / 7 nodes)</small><strong>${visited.join(' → ')||'Start'}</strong><small>Next to visit: ${next||'Done'}</small></div><p class="lab-story mt-2">${p.alg==='BFS'?'A FIFO queue grows the search frontier layer by layer.':'A LIFO stack follows one branch deeply before backtracking.'}</p>`;
 }
 return {svg,values};}
function refreshLab(){if(state.view!=='labs')return;const v=labDraw();if($('#lab-visual'))$('#lab-visual').innerHTML=v.svg;if($('#lab-values'))$('#lab-values').innerHTML=v.values;for(let [k,val] of Object.entries(state.labParams)){let el=$('#label-'+k);if(el)el.textContent=val+(['prev','sens','fpr'].includes(k)?'%':'');}}

async function toggleTopic(id){let prev=!!state.progress.topics[id];state.progress.topics[id]=!prev;render(false);try{await api('/api/topic',{id,completed:!prev});toast(prev?'Concept marked for review.':'Concept saved as mastered.');}catch(e){state.progress.topics[id]=prev;render(false);toast(e.message);}}
async function updateTask(day,task,complete){state.progress.day_tasks[day]??={};let prev=state.progress.day_tasks[day][task];state.progress.day_tasks[day][task]=complete;render(false);try{await api('/api/day',{day,task,completed:complete});toast('Daily checklist saved.')}catch(e){state.progress.day_tasks[day][task]=prev;render(false);toast(e.message);}}
function setAnswer(value){const q=state.quiz;if(!q)return;q.answers[q.ids[q.index]]=value;render(false);}

// Event delegation allows a responsive, dependency-free single-page application.
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el||el.disabled)return;
 try{
 if(el.dataset.view){goto(el.dataset.view);return;}
 if(el.dataset.day){goto('day',{number:el.dataset.day});return;}
 if(el.dataset.lesson){goto('lesson',{id:el.dataset.lesson});return;}
 if(el.dataset.subject){goto('syllabus-detail',{subject:el.dataset.subject});return;}
 if(el.dataset.revealCheck){const answer=$('#concept-check-answer');if(answer){answer.hidden=!answer.hidden;el.textContent=answer.hidden?'Reveal the explanation':'Hide the explanation';el.setAttribute('aria-expanded',String(!answer.hidden));}return;}
 if(el.dataset.topicToggle){await toggleTopic(el.dataset.topicToggle);return;}
 if(el.dataset.dailyQuiz){launchDaily(el.dataset.dailyQuiz);return;}
 if(el.dataset.topicQuiz){let ids=qs().filter(q=>q.lesson_id===el.dataset.topicQuiz).map(q=>q.id);startQuiz(ids,'Concept check: '+lessonById(el.dataset.topicQuiz).title);return;}
 if(el.dataset.flashReveal){state.flashRevealed=true;render(false);return;}
 if(el.dataset.flashNav){const n=flashDeck().length;state.flashIndex=Math.max(0,Math.min(n-1,state.flashIndex+(el.dataset.flashNav==='next'?1:-1)));state.flashRevealed=false;render(false);return;}
 if(el.dataset.flashAll){state.flashMode='all';state.flashIndex=0;state.flashRevealed=false;render(false);return;}
 if(el.dataset.flashRate){const card=flashDeck()[state.flashIndex];if(!card)return;const outcome=await api('/api/recall',{id:card.id,rating:el.dataset.flashRate});state.progress.recalls[card.id]={rating:outcome.rating,due_date:outcome.due_date,interval_days:outcome.interval_days,repetitions:outcome.repetitions};if(state.flashMode!=='due')state.flashIndex=Math.min(flashDeck().length-1,state.flashIndex+1);state.flashRevealed=false;render(false);toast('Recall scheduled for '+fmtDate(outcome.due_date));return;}
 if(el.dataset.practiceSub){state.practiceSub=el.dataset.practiceSub;goto('practice');return;}
 if(el.dataset.startCustom){launchCustom();return;}
 if(el.dataset.startMock){launchMock();return;}
 if(el.dataset.option!==undefined){let q=qById(state.quiz.ids[state.quiz.index]);let i=Number(el.dataset.option),old=state.quiz.answers[q.id];if(q.type==='MSQ'){let a=Array.isArray(old)?[...old]:[];a=a.includes(i)?a.filter(x=>x!==i):[...a,i];setAnswer(a);}else setAnswer(i);return;}
 if(el.dataset.qIndex!==undefined){state.quiz.index=Number(el.dataset.qIndex);render(false);return;}
 if(el.dataset.qPrev){state.quiz.index=Math.max(0,state.quiz.index-1);render(false);return;}
 if(el.dataset.qNext){state.quiz.index=Math.min(state.quiz.ids.length-1,state.quiz.index+1);render(false);return;}
 if(el.dataset.quizExit){if(confirm('Leave this quiz? Current unsent answers will be lost.'))goto('practice');return;}
 if(el.dataset.quizSubmit){await submitQuiz();return;}
 if(el.dataset.saveNote){let note=$('#lesson-note').value;await api('/api/note',{id:el.dataset.saveNote,text:note});state.progress.notes[el.dataset.saveNote]=note;toast('Your note is safely stored.');return;}
 if(el.dataset.lab){state.lab=el.dataset.lab;goto('labs');return;}
 if(el.dataset.alg){state.labParams.alg=el.dataset.alg;state.labParams.step=0;render(false);return;}
 if(el.dataset.step){state.labParams.step=Math.min(7,state.labParams.step+1);refreshLab();return;}
 if(el.dataset.stepReset){state.labParams.step=0;refreshLab();return;}
 if(el.dataset.saveMinutes){let minutes=Number($('#daily-minutes').value);await api('/api/setting',{key:'daily_minutes',value:minutes});state.progress.settings.daily_minutes=String(minutes);toast('Daily study target saved.');return;}
 if(el.dataset.export){let data=await api('/api/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='gate_da_studyos_backup.json';a.click();URL.revokeObjectURL(url);toast('Backup exported.');return;}
 if(el.dataset.importOpen){$('#import-file').click();return;}
 if(el.dataset.reset){const confirmText=prompt('This deletes every checklist, quiz result and note. Type RESET to continue:');if(confirmText==='RESET'){let x=await api('/api/reset',{confirm:'RESET'});state.progress=x.progress;render();toast('Progress reset.')}return;}
 if(el.id==='logout-button'){await api('/api/logout',{});csrfToken=null;account=null;state.content=null;state.progress=null;state.quiz=null;state.result=null;clearInterval(timerInterval);showAuth();return;}
 if(el.id==='focus-toggle'){state.focus=!state.focus;document.body.classList.toggle('focus-mode',state.focus);el.textContent=state.focus?'Exit focus mode':'Focus mode';return;}
 if(el.id==='menu-toggle'){$('#sidebar').classList.toggle('open');return;}
 }catch(e){console.error(e);toast(e.message||'Could not complete the action.');}
});
document.addEventListener('change',async event=>{const el=event.target;
 if(el.dataset.dayCheck){await updateTask(el.dataset.dayCheck,el.dataset.task,el.checked);return;}
 if(el.id==='flash-mode'){state.flashMode=el.value;state.flashIndex=0;state.flashRevealed=false;render(false);return;}
 if(el.id==='flash-sub'){state.flashSub=el.value;state.flashIndex=0;state.flashRevealed=false;render(false);return;}
 if(el.id==='month-filter'){state.month=el.value;render(false);return;}
 if(el.id==='practice-sub'){state.practiceSub=el.value;return;}
 if(el.id==='practice-count'){state.practiceCount=Number(el.value);return;}
 if(el.id==='practice-difficulty'){state.practiceDifficulty=el.value;return;}
 if(el.id==='import-file'&&el.files.length){try{const obj=JSON.parse(await el.files[0].text());if(!confirm('Restore this backup? This REPLACES the current progress database.'))return;let response=await api('/api/import',{backup:obj});state.progress=response.progress;render();toast('Backup restored successfully.');}catch(e){toast('Restore failed: '+e.message);}return;}
});
document.addEventListener('input',event=>{let el=event.target;
 if(el.id==='dice-sum'){state.diceSum=Number(el.value);const temp=document.createElement('div');temp.innerHTML=renderDiceMicro();const grid=temp.querySelector('#dice-grid'),result=temp.querySelector('#dice-result');if($('#dice-grid'))$('#dice-grid').innerHTML=grid.innerHTML;if($('#dice-result'))$('#dice-result').innerHTML=result.innerHTML;if($('#dice-target'))$('#dice-target').textContent=state.diceSum;return;}
 if(el.dataset.pyA||el.dataset.pyB){if(el.dataset.pyA)state.pyA=Number(el.value);else state.pyB=Number(el.value);const temp=document.createElement('div');temp.innerHTML=renderPythonMicro();if($('#python-results'))$('#python-results').innerHTML=temp.querySelector('#python-results').innerHTML;return;}
 if(el.id==='nat-answer'&&state.quiz){state.quiz.answers[state.quiz.ids[state.quiz.index]]=el.value;return;}
 if(el.id==='syllabus-search'){state.search=el.value;const position=el.selectionStart;const results=el.parentElement.nextElementSibling;if(results)results.outerHTML=renderSearchResults();return;}
 if(el.dataset.range){state.labParams[el.dataset.range]=Number(el.value);refreshLab();return;}
});
let registerMode=false;
let allowRegistrations=true;
function showAuth(){
  $('#app').hidden=true;
  $('#auth-screen').hidden=false;
  document.body.classList.remove('focus-mode');state.focus=false;
  setAuthMode(registerMode);
}
function setAuthMode(reg){
  registerMode=reg;
  $('#auth-title').textContent=reg?'Start your journey':'Welcome back';
  $('#auth-subtitle').textContent=reg?'Create a personal workspace in seconds.':'Sign in to pick up where you left off.';
  $('#auth-display-wrap').hidden=!reg;
  $('#auth-display').required=reg;
  $('#auth-password').autocomplete=reg?'new-password':'current-password';
  $('#auth-submit').innerHTML=reg?'Create my account <span>→</span>':'Log in to StudyOS <span>→</span>';
  $('#auth-mode-login').classList.toggle('active',!reg);
  $('#auth-mode-register').classList.toggle('active',reg);
  $('#auth-error').hidden=true;
  $('#auth-mode-register').hidden=!allowRegistrations;
  $('#auth-help').textContent=reg?'Choose a unique username and a strong password of at least 10 characters.':'Sign in with the same account from any device to see your saved progress.';
}
async function loadWorkspace(){
  const data=await api('/api/bootstrap');
  state.content=data.content;state.progress=data.progress;state.serverDate=data.server_date;
  state.selectedDay=todayDefaultDay()?.number||1;state.view='today';state.quiz=null;state.result=null;
  $('#account-display').textContent=account?.display_name||account?.username||'Learner';
  $('#auth-screen').hidden=true;$('#app').hidden=false;
  render();
}
$('#auth-mode-login').addEventListener('click',()=>setAuthMode(false));
$('#auth-mode-register').addEventListener('click',()=>setAuthMode(true));
$('#auth-form').addEventListener('submit',async event=>{
  event.preventDefault();
  const button=$('#auth-submit');button.disabled=true;
  const error=$('#auth-error');error.hidden=true;
  try{
    const payload={username:$('#auth-username').value.trim(),password:$('#auth-password').value};
    if(registerMode)payload.display_name=$('#auth-display').value.trim();
    const resp=await api(registerMode?'/api/register':'/api/login',payload);
    account=resp.user;csrfToken=resp.csrf_token;
    $('#auth-password').value='';
    await loadWorkspace();
    toast('Welcome '+account.display_name+'! Your progress is private.');
  }catch(e){error.textContent=e.message;error.hidden=false;}
  finally{button.disabled=false;}
});
document.addEventListener('submit',async event=>{
  if(event.target.id!=='change-password-form')return;
  event.preventDefault();
  try{
    await api('/api/change-password',{old_password:$('#old-password').value,new_password:$('#new-password').value});
    event.target.reset();toast('Password updated. Other sessions were signed out.');
  }catch(e){toast(e.message);}
});
(async function boot(){
  try{
    const status=await api('/api/me');allowRegistrations=status.registration_enabled;
    if(!status.authenticated){showAuth();return;}
    account=status.user;csrfToken=status.csrf_token;
    await loadWorkspace();
  }catch(e){
    $('#auth-screen').hidden=false;$('#app').hidden=true;
    $('#auth-error').textContent='Could not reach the StudyOS backend: '+e.message;$('#auth-error').hidden=false;
    setAuthMode(false);
    $('#auth-error').textContent='Could not connect to the server. Run python server.py then open the local address.';$('#auth-error').hidden=false;
  }
})();
